const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const coreChecks=new Map(),calculationVisibility=new Map();
const KEY='xiangqi-lab-v1';let storageWarning='',protectStoredRecord=false,invalidStoredRaw=null;let saved=createState(E.VALUES);let storedBaseline=null,storageConflict=false,saveQueue=Promise.resolve(),saveRequest=0,pythonResultGeneration=0;
let transfers=[],activities={},pythonScope='core',transferResultText='',transferResultType='',reflectionMessage='';
let curriculum,positions,exercises,units,current,tab='code',view='lab',b,side,initial,selected=null,boardMessage='',resultText='目标函数仍是空白。写好后先运行示例测试，再提交挑战。',resultType='',pythonWorker=null,pythonTimer=null,pythonBusy=false,searchWorker=null,trace=null,cursor=0,playing=null,traceBoard=false,tracePage=0,selectedFixture='lesson';
