const stateOptions=()=>({fixtureIds:allFixtures().map(f=>f.id),fixtures:allFixtures(),transfers});
const currentTransfer=()=>transfers.find(task=>task.unit_id===current.unit_id);
function transferAnswer(){const task=currentTransfer();return saved.transfers[task.id]||{code:task.starter,explanation:'',hints:0,answerViewed:false};}
function updateTransfer(change){const task=currentTransfer();saved.transfers[task.id]={...transferAnswer(),...change};return save();}
function coreCheck(id){const check=coreChecks.get(id);return check&&check.source===(saved.codes[id]??exercises.find(e=>e.id===id)?.starter)?check:null;}
function coreLabel(id){const check=coreCheck(id),previous=saved.passed.includes(id);if(check?.challenge&&check.passed===check.total)return '本次挑战已通过';if(check&&check.passed<check.total)return previous?'曾通过，本次待修复':'本次待修复';return previous?'记录曾通过':'可自由实验';}
function reviewLabel(id){const check=coreCheck(id);if(check?.challenge&&check.passed===check.total)return '本次已修复，可复习';if(check&&check.passed===check.total)return '示例已通过，待挑战验证';return saved.passed.includes(id)?(check?'曾通过，本次待修复':'曾通过，错误待复习'):'待再试';}
function refreshProgress(){const passed=new Set(saved.passed),counter=$('.sidebar .row .tiny');if(counter)counter.textContent=`${passed.size} / ${exercises.length}`;const bar=$('.sidebar .progress div');if(bar)bar.style.width=passed.size/exercises.length*100+'%';for(const el of $$('.unit-title')){const count=el.querySelector('small');if(count)count.textContent=exercises.filter(e=>e.unit_id===Number(el.dataset.unit)&&passed.has(e.id)).length+'/3'}for(const el of $$('.exercise-link')){const e=exercises.find(e=>e.id===el.dataset.lesson);el.textContent=(passed.has(e.id)?'✓ ':'')+e.title;}const review=$('[data-action=review] span');if(review)review.textContent=Object.keys(saved.mistakes).length;const tag=$('.lesson-header .tag');if(tag)tag.textContent=coreLabel(current.id);}
function feedbackTip(message,scope='core'){const run=scope==='transfer'?'运行迁移自查':'运行示例';if(/SyntaxError|IndentationError|TabError/.test(message))return '先检查提示行附近的冒号、括号与缩进；修正后'+run+'。';if(/ZeroDivisionError/.test(message))return '检查除数是否为0；用提示行的输入复现，再为零值补边界处理。';if(/RecursionError/.test(message))return '检查递归出口与每次是否减少深度；先用深度0和1验证。';if(/NameError/.test(message))return '检查提示行中的名字是否拼对、是否先定义；脚手架允许的函数列在输入/输出契约。';if(/TypeError|IndexError|KeyError/.test(message))return '对照输入/输出契约检查类型、board[y][x]与边界；用一个可见示例定位提示行。';if(/NotImplementedError/.test(message))return '目标函数仍有待填写处。先预测，再展开第一层提示；参考解答需要你明确点击。';return '先比较失败示例的输入、实际与期望，再检查一个边界或反例。隐藏测试不公布输入；'+(scope==='transfer'?'可逐层查看本页提示，修改后运行迁移自查。':'可逐层查看提示，并从复习入口返回重试。');}
function errorSummary(message){const lines=String(message).trim().split('\n'),line=String(message).match(/File "<student>", line (\d+)/);return (line?'代码第 '+line[1]+' 行：':'')+lines.at(-1).trim().slice(0,300);}
function transferRecordStatus(){const answer=transferAnswer(),check=answer.lastCheck;if(!check)return '迁移代码尚未自查；解释由你对照问题检查。';return check.source!==answer.code?'代码已修改，旧自查只对应上次提交；需重新运行。':`上次迁移自查 ${check.passed}/${check.total} 通过；解释未被自动判正确。${answer.answerViewed?' 已查看参考解答。':''}`;}
const conflictMessage='另一页更新了学习记录。本页已暂停自动保存，草稿仍保留。请先导出本页草稿，再载入最新记录。';
function writeStored(build,guard=()=>true,onCommitted=()=>{}){const job=saveQueue.catch(()=>{}).then(()=>{if(!navigator.locks?.request)throw Error('浏览器不支持跨页保存锁；草稿仍在本页，请导出备份。');return navigator.locks.request(KEY+'-save',{mode:'exclusive'},()=>{if(!guard())throw Error('较早的导入请求已取消');if(localStorage.getItem(KEY)!==storedBaseline){storageConflict=true;showStorageWarning(conflictMessage);throw Error(conflictMessage)}const raw=typeof build==='function'?build():build;localStorage.setItem(KEY,raw);storedBaseline=raw;storageConflict=false;onCommitted();})});saveQueue=job;return job;}
addEventListener('storage',event=>{if(event.key===KEY||event.key===null){try{if(localStorage.getItem(KEY)!==storedBaseline){storageConflict=true;showStorageWarning(conflictMessage)}}catch{showStorageWarning('浏览器存储不可读；草稿仍在本页，请导出备份。')}}});
const storageDescription='代码、进度和设置仅保存在当前浏览器。用「记录与导出」备份或在另一设备导入。';
function showStorageWarning(message){storageWarning=message;const element=$('#storage-warning');if(element)element.textContent=message||storageDescription;const reload=$('#reload-latest');if(reload)reload.hidden=!storageConflict;}
function restoreLocalState(){try{const raw=localStorage.getItem(KEY);storedBaseline=raw;if(raw!==null){invalidStoredRaw=raw;saved=parseRecord(raw,exercises,E.VALUES,stateOptions()).state;invalidStoredRaw=null;}}catch(error){protectStoredRecord=true;showStorageWarning('本地记录无法读取：'+error.message+'。原记录未覆盖；当前修改仅保存在本次页面，请导出备份。')}}
const save=async()=>{if(protectStoredRecord)return false;const request=++saveRequest;if(!storageConflict)showStorageWarning('正在保存本页修改…');try{await writeStored(()=>encodeRecord(saved,exercises,E.VALUES,stateOptions()));if(request===saveRequest)showStorageWarning(storageConflict?conflictMessage:'');return true}catch(error){showStorageWarning(storageConflict?conflictMessage:'保存失败：'+error.message+'。当前修改仅保存在本次页面，请导出备份。');return false}};
function normalizeBoard(v){if(Array.isArray(v)&&v.length===10)return v.map(r=>typeof r==='string'?r.split(''):r.slice());if(Array.isArray(v)&&v[0]?.length===3)return E.board(v);return E.board([[4,9,'K'],[3,0,'k'],[4,6,'P'],[0,8,'R'],[0,2,'r']])}
function adoptSession(next){session=next;b=next.board;side=next.side;initial=next.initial;selectedFixture=next.fixture;}
function persistLab(){saved.labs[current.id]=structuredClone(session);return save()}
