function setLesson(id,push=true,persist=true){pythonResultGeneration++;clearBoardResult();editDraft=null;if(pythonBusy)stopPython('切换题目，已停止上一题运行；代码仍保留在本次页面。');const e=exercises.find(e=>e.id===id)||exercises[0];current=e;if(push)history.replaceState(null,'','#'+e.id);saved.lastExercise=e.id;adoptSession(saved.labs[e.id]?L.validateSession(saved.labs[e.id],stateOptions()):L.createSession(e.lab.board,e.lab.side));selected=null;cursor=0;if(persist)persistLab();const restoredFixture=allFixtures().find(f=>f.id===selectedFixture);boardMessage=selectedFixture==='custom'?'已恢复自定义实验棋盘与操作历史。':restoredFixture?(restoredFixture.purposeZh||restoredFixture.title||restoredFixture.titleZh):(saved.predictions[e.id]?e.lab.objective:'本题初始局面：先预测，或主动操作并展开计算结果核对。');resultText=saved.passed.includes(e.id)?'学习记录曾通过本题，已恢复你的代码；修改后需重新运行验证。':saved.codes[e.id]!==undefined&&saved.codes[e.id]!==e.starter?'已恢复你的代码。先运行示例排错，再提交挑战。':'目标函数仍是空白。写好后先运行示例测试，再提交挑战。';resultType='';transferResultText='';transferResultType='';reflectionMessage='';view='lab';render({focus:push?'#lesson-title':undefined})}
async function reloadLatest(){if(!confirm('将载入另一页的最新记录，替换本页尚未保存的草稿。请先导出本页草稿。继续？'))return;await saveQueue.catch(()=>{});try{const raw=localStorage.getItem(KEY),candidate=raw===null?createState(E.VALUES):parseRecord(raw,exercises,E.VALUES,stateOptions()).state;saved=candidate;storedBaseline=raw;storageConflict=false;protectStoredRecord=false;invalidStoredRaw=null;showStorageWarning('');$$('.modal-backdrop').forEach(el=>el.remove());setLesson(saved.lastExercise||current.id,true,false)}catch(error){showStorageWarning('最新记录无法载入：'+error.message+'；本页草稿仍保留。')}}
function layout(){const passed=new Set(saved.passed);return `<header class="topbar"><div class="brand"><div class="brand-mark" aria-hidden="true">象</div><div><h1>中国象棋 AI 编程闯关实验室</h1><div class="tiny muted">规则 → 状态 → 搜索 · Python 本地运行</div></div></div><div class="top-actions"><button class="map-btn" data-action="map">学习地图</button><button data-action="review">复习 <span>${Object.keys(saved.mistakes).length}</span></button><button class="storage-btn" data-action="storage">记录与导出</button><button class="quiet" data-action="diagnosis" aria-label="基础诊断">诊断</button></div></header><div class="layout"><aside class="sidebar"><div class="row"><strong>8 个单元</strong><span class="tiny muted">${passed.size} / ${exercises.length}</span></div><div class="progress"><div style="width:${passed.size/exercises.length*100}%"></div></div>${units.map(u=>`<div class="unit"><button class="unit-title" data-unit="${u.id}"><span>${String(u.id).padStart(2,'0')} ${esc(u.title)}</span><small>${exercises.filter(e=>e.unit_id===u.id&&passed.has(e.id)).length}/3</small></button>${exercises.filter(e=>e.unit_id===u.id).map(e=>`<button class="exercise-link ${e.id===current.id?'active':''}" data-lesson="${e.id}">${passed.has(e.id)?'✓ ':''}${esc(e.title)}</button>`).join('')}</div>`).join('')}<div class="sidebar-footer">✓ 与计数表示历史挑战记录，不代表理解或当前代码验证<br>所有单元可直接预览<br>每单元约 20–40 分钟<br><button class="quiet tiny" data-action="about">范围与规则来源</button></div></aside><div><nav class="mobile-nav"><select id="mobile-lesson" aria-label="选择练习">${exercises.map(e=>`<option value="${e.id}" ${e.id===current.id?'selected':''}>${e.unit_id} · ${esc(e.title)}</option>`).join('')}</select><button data-action="map">地图</button><button data-action="storage">记录</button></nav><main class="workspace" id="workspace">${view==='map'?mapHTML():view==='review'?reviewHTML():lessonHTML()}</main></div></div>`}
function mapHTML(){return `<div class="lesson-header"><div><div class="eyebrow">LEARNING PATH / 学习路线</div><h2>从一枚棋子，到一棵搜索树</h2><p class="muted">先预测，再操作，再用 Python 验证。可按顺序学习，也可从诊断建议开始。</p></div><button data-action="diagnosis">做基础诊断</button></div><div class="map-grid">${units.map(u=>`<article class="card map-card"><span class="tag">单元 ${u.id} · 20–40 分钟</span><h3>${esc(u.title)}</h3><p>${esc(u.overview||u.goal||u.summary||'用短局面把规则拆成可测试的函数。')}</p><ul>${exercises.filter(e=>e.unit_id===u.id).map(e=>`<li>${esc(e.title)}</li>`).join('')}</ul><button class="primary" data-lesson="${exercises.find(e=>e.unit_id===u.id).id}">进入单元 ${saved.passed.filter(id=>exercises.find(e=>e.id===id)?.unit_id===u.id).length}/3</button></article>`).join('')}</div><p class="footer-note">进度只保存在当前浏览器；这不是跨设备同步。教学有效性尚待真实学习者验证。</p>`}
function reviewHTML(){const ids=Object.keys(saved.mistakes);return `<div class="lesson-header"><div><div class="eyebrow">REVIEW / 错误与再试</div><h2>把错误变成下一次预测</h2><p class="muted">记录最近的失败提交。历史曾通过不证明当前代码正确；修复并重新提交后，可移出复习。</p></div></div><div class="card">${ids.length?ids.map(id=>{const e=exercises.find(e=>e.id===id),m=saved.mistakes[id];return e?`<div class="review-item"><div class="row"><strong>${esc(e.title)}</strong><span class="tag">${reviewLabel(id)}</span></div><p class="tiny muted">${esc(m.message)} · ${new Date(m.at).toLocaleString('zh-CN')}</p><button data-lesson="${id}">回到练习</button> <button data-resolve="${id}">移出复习</button></div>`:''}).join(''):`<div class="empty">还没有错误记录<br><span class="tiny">失败不会丢失代码，修改后可随时重试</span></div>`}</div>`}
function lessonHTML(){const u=units.find(u=>u.id===current.unit_id);return `<div class="lesson-header"><div><div class="eyebrow">UNIT ${String(current.unit_id).padStart(2,'0')} / ${esc(u.title)}</div><h2 id="lesson-title" tabindex="-1">${esc(current.title)}</h2><div class="tiny muted">${esc(current.signature||current.function+'(...)')} <span class="tag">${coreLabel(current.id)}</span></div></div><button data-action="next">下一题 →</button></div><div class="workspace-grid"><section class="card board-card" aria-label="象棋操作实验"><div class="board-head"><strong>局面实验</strong><span class="tag" id="turn-label"></span></div><div id="board-host"></div><div class="board-controls"><select id="fixture-select" aria-label="选择教学局面"><option value="lesson" ${selectedFixture==='lesson'?'selected':''}>本题操作局面</option><option value="custom" ${selectedFixture==='custom'?'selected':''} ${selectedFixture==='custom'?'':'hidden'}>自定义实验局面</option>${(current.lab.presets||[]).map(p=>`<option value="${current.id+'-'+p.id}" ${selectedFixture===current.id+'-'+p.id?'selected':''}>${esc(p.title)}</option>`).join('')}<option value="${currentTransfer().lab.id}" ${selectedFixture===currentTransfer().lab.id?'selected':''}>${esc(currentTransfer().lab.title)}</option>${positions.fixtures.map(p=>`<option value="${p.id}" ${selectedFixture===p.id?'selected':''}>${esc(p.titleZh)}</option>`).join('')}</select><button data-action="reset-board">重置</button><button data-action="switch-side" aria-label="切换行棋方">换方</button></div><div class="action-row board-actions"><button data-action="edit-board">摆棋编辑</button><button data-action="undo-board" id="undo-board">撤销一步</button><button data-action="simulate-board" id="simulate-board">试走并还原</button></div><p class="board-note" id="board-note"></p><details id="board-calculation" data-exercise="${current.id}" ${calculationVisibility.has(current.id)?(calculationVisibility.get(current.id)?'open':''):(saved.predictions[current.id]?'open':'')}><summary id="board-calc-toggle">查看计算结果（可能包含预测答案）</summary><div class="metric-row"><div class="metric"><strong id="legal-count">—</strong><span>当前方合法着法</span></div><div class="metric"><strong id="evaluation">—</strong><span>红方视角分数</span></div><div class="metric"><strong id="check-status">—</strong><span>当前状态</span></div></div><div id="computed-detail"></div></details><div id="board-detail"></div><p class="tiny muted" style="margin:13px 0 0">坐标 (x,y)：左上 (0,0)，右下 (8,9)<br>点击棋子看合法目标；手机可完成预测与局面实验</p></section><section class="card lesson-panel"><nav class="tabs" aria-label="学习步骤">${[['concept','理解'],['predict','预测'],['code','编程'],['search','搜索树'],['reflect','解释'],['transfer','迁移']].map(([k,l])=>`<button data-tab="${k}" class="${tab===k?'active':''}" aria-pressed="${tab===k}">${l}</button>`).join('')}</nav><div class="panel-body" id="panel-body">${panelHTML()}</div></section></div><p class="footer-note"><span id="storage-warning">${esc(storageWarning||storageDescription)}</span> <button id="reload-latest" class="quiet tiny" data-action="reload-storage" ${storageConflict?'':'hidden'}>载入最新记录</button> <button class="quiet tiny" data-action="about">规则边界 / 数据说明</button></p>`}
function panelHTML(){if(tab==='reflect')return reflectionHTML();if(tab==='transfer')return transferHTML();if(tab==='concept')return `<h3>先把问题想清楚</h3><div class="concept">${Array.isArray(current.concepts)?`<ul>${current.concepts.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`:esc(current.concepts)}</div><p>${esc(current.explanation)}</p><div class="callout"><strong>单元知识与先修入口</strong><p>${esc(units.find(u=>u.id===current.unit_id)?.knowledge)}</p><p class="tiny">${esc(units.find(u=>u.id===current.unit_id)?.prerequisite)}</p></div><div class="callout"><strong>操作实验</strong><p style="margin:5px 0 0">用左侧本题局面动手检验；操作步骤与结果核对可以主动展开。</p></div><button class="primary" data-tab="predict">先做预测 →</button><p class="tiny muted">必要语法：${esc(activities[current.id]?.syntax)}</p>${activities[current.id]?.syntax_example?`<details><summary>新语法小例子（不填写目标函数）</summary><pre>${esc(activities[current.id].syntax_example)}</pre></details>`:''}<details id="operation-check"><summary>展开操作步骤与核对（可能包含预测答案）</summary><p>${esc(current.lab.objective)}</p><ol>${activities[current.id].steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><p>${esc(activities[current.id].explain)}</p></details><button data-tab="reflect">进入解释与自查</button> <button data-tab="transfer">进入本单元独立迁移题</button>`;
if(tab==='predict'){const p=current.prediction,ans=saved.predictions[current.id];return `<h3>运行前，先选你的判断</h3><p class="tiny muted">预测基于本题初始局面和默认棋子价值。左侧实验与评分参数的变化不会改写这道固定题的答案。</p><p>${esc(p.question)}</p><fieldset style="border:0;padding:0;margin:0"><legend class="sr-only">预测答案</legend>${p.choices.map((c,i)=>`<label class="prediction-choice"><input type="radio" name="prediction" value="${i}" ${ans?.choice===i?'checked':''}>${esc(c)}</label>`).join('')}</fieldset><button class="primary" data-action="check-prediction">检查预测</button>${ans?`<div class="callout ${ans.choice===p.answer_index?'':'warning'}"><strong>${ans.choice===p.answer_index?'判断正确':'再想一想'}</strong><p style="margin:5px 0 0">${esc(p.explanation)}</p></div>`:''}<p class="tiny muted">改变棋盘上的一枚棋子，再尝试解释为什么答案会变或不变。</p>`}
if(tab==='search')return searchHTML();
return `<div class="code-heading"><h3 style="margin:0">实现核心函数</h3><span class="tiny muted">Python 3 · 独立 Worker</span></div><p class="tiny muted">${esc(current.prompt||current.task||current.explanation)}<br>先用示例排错，再运行未预先展示的挑战测试。桌面更适合编辑。</p><details class="contract"><summary>输入/输出契约与可用脚手架</summary><p>${esc(current.prompt)}</p><p class="tiny">${esc(current.scaffold_note)}<br>可直接使用：${esc(current.allowed_helpers?.join("、")||"无；本题逻辑由你填写")}</p><pre>${esc(current.visible_tests.map(t=>t.name+"\n输入："+JSON.stringify(t.args)+"\n期望："+JSON.stringify(t.expected)).join("\n\n"))}</pre></details><label class="sr-only" for="code-editor">Python 代码编辑器</label><p class="tiny muted" id="editor-keys">Tab 缩进；Shift+Tab 返回前一控件；Esc 离开编辑器；Ctrl+Enter 运行示例。</p><textarea aria-describedby="editor-keys" id="code-editor" class="editor" maxlength="100000" spellcheck="false" autocapitalize="off" autocomplete="off">${esc(saved.codes[current.id]??current.starter)}</textarea><div class="action-row"><button class="primary" id="run-visible" data-action="run-visible" ${pythonBusy?'disabled':''}>运行示例</button><button id="run-hidden" data-action="run-hidden" ${pythonBusy?'disabled':''}>提交挑战</button><button class="danger" id="stop-python" data-action="stop-python" ${!pythonBusy?'disabled':''}>停止</button><button class="quiet" data-action="restore-starter">重置代码</button></div><div id="python-result" class="result ${resultType}" role="status" aria-live="polite">${esc(resultText)}</div><div class="hints"><div class="row"><strong class="tiny">卡住了？逐步提示</strong><button data-action="hint">提示 ${(saved.hints[current.id]||0)}/3</button></div>${current.hints.slice(0,saved.hints[current.id]||0).map((h,i)=>`<div class="hint">${i+1}. ${esc(h.text??h)}</div>`).join('')}<button class="quiet tiny" data-action="solution">明确查看参考解答</button><span class="tiny muted">不会自动替换你的代码</span></div>`}
function reflectionHTML(){const activity=activities[current.id];return `<h3>用自己的话解释一次结果</h3><p>${esc(activity.explain)}</p><label for="reflection-editor">你的解释与反例（最多4000字符）</label><textarea id="reflection-editor" class="reflection-editor" maxlength="4000">${esc(saved.reflections[current.id]||'')}</textarea><button data-action="save-reflection">保存并对照自查</button><p id="reflection-status" role="status">${esc(reflectionMessage||'解释草稿保存在当前浏览器；文字有填写不代表解释正确。')}</p><div class="callout"><strong>自己核对</strong><ul>${activity.checks.map(text=>`<li>${esc(text)}</li>`).join('')}</ul><p class="tiny muted">测试能检查代码的输入输出，不能代替你解释为什么。请用棋盘或新输入检验自己的说法。</p></div><button class="primary" data-tab="transfer">尝试新输入 →</button>`;}
function transferHTML(){const task=currentTransfer(),answer=transferAnswer();return `<div class="row"><h3>${esc(task.title)}</h3><span class="tag">单元 ${task.unit_id} 独立迁移</span></div><p>${esc(task.prompt)}</p><p class="tiny muted">先修：本单元三题；${esc(task.knowledge)}</p>${task.syntax_example?`<details><summary>迁移所需的新语法小例子</summary><pre>${esc(task.syntax_example)}</pre><button data-lesson="u04e03">自由预览 try/finally 课</button></details>`:''}<button data-action="transfer-position">载入迁移实验局面</button><details class="contract"><summary>输入/输出示例与可用脚手架</summary><p>可直接使用：${esc(task.allowed_helpers.join('、')||'Python基本语法，由你实现目标逻辑')}</p><pre>${esc(task.visible_tests.map(t=>t.name+'\n输入：'+JSON.stringify(t.args)+'\n期望：'+JSON.stringify(t.expected)).join('\n\n'))}</pre></details><label for="transfer-editor">手写迁移函数：${esc(task.signature)}</label><p class="tiny muted" id="transfer-keys">Tab 缩进；Shift+Tab 返回；Esc 离开编辑器；Ctrl+Enter 自查。</p><textarea class="editor" id="transfer-editor" maxlength="100000" aria-describedby="transfer-keys" spellcheck="false" autocapitalize="off">${esc(answer.code)}</textarea><div class="action-row"><button id="run-transfer" class="primary" data-action="run-transfer" ${pythonBusy?'disabled':''}>运行迁移自查</button><button id="stop-transfer" data-action="stop-python" ${!pythonBusy?'disabled':''}>停止</button><button data-action="transfer-hint">迁移提示 ${answer.hints}/3</button><button data-action="transfer-solution">明确查看迁移解答</button></div><p id="transfer-record-status" class="tiny muted">${esc(transferRecordStatus())}</p><div id="transfer-result" class="result ${transferResultType}" role="status">${esc(transferResultText||(answer.code!==task.starter?'已恢复迁移代码，请重新运行自查。不会替换答案或增加核心24题计数。':'目标函数待你填写。自查会真实执行提交代码；不会替换答案或增加核心24题计数。'))}</div>${task.hints.slice(0,answer.hints).map((hint,i)=>`<div class="hint">${i+1}. ${esc(hint)}</div>`).join('')}<h3>把迁移解释清楚</h3><p>${esc(task.explain_prompt)}</p><label for="transfer-explanation">你的解释与下一次检验</label><textarea id="transfer-explanation" class="reflection-editor" maxlength="4000">${esc(answer.explanation)}</textarea><button data-action="save-transfer-explanation">保存解释并自查</button><p id="transfer-explanation-status" role="status">解释只保存为草稿，尚未由真人验证。</p><details><summary>解释自查问题</summary><ul><li>你是否用具体输入说明了结论？</li><li>换一个边界或阵营后，你的理由还成立吗？</li><li>这次测试能证明什么，还有哪些结论不能证明？</li></ul></details>`;}
function searchHTML(){return `<h3>让每一层选择都看得见</h3><p class="tiny muted">固定红方视角（red-fixed）：红方取最大，黑方取最小。深度是剩余半回合（ply），先判终局再评估。当前棋盘产生真实搜索轨迹。</p><div class="search-controls"><label>算法<select id="search-algo"><option value="alphabeta" ${saved.settings.algo==='alphabeta'?'selected':''}>Alpha-beta 剪枝</option><option value="minimax" ${saved.settings.algo==='minimax'?'selected':''}>Minimax 极大极小</option></select></label><label>深度<select id="search-depth">${[0,1,2,3].map(v=>`<option ${saved.settings.depth===v?'selected':''}>${v}</option>`).join('')}</select></label><label>走法顺序<select id="search-order"><option value="lex" ${saved.settings.order==='lex'?'selected':''}>坐标字典序</option><option value="capture" ${saved.settings.order==='capture'?'selected':''}>吃子优先</option></select></label>${['R','C','H','P'].map(k=>`<label>${{R:'车',C:'炮',H:'马',P:'兵'}[k]}价值<input type="number" min="0" max="10000" step="10" data-weight="${k}" value="${saved.settings.values[k]}"></label>`).join('')}</div><div class="action-row"><button class="primary" data-action="compute-search">重新计算</button><button data-action="stop-search">停止计算</button><button data-action="compare-search">比较两算法</button></div><div id="search-status" class="tiny muted">${searchMessage|| (trace?`分数 ${trace.score} · 最佳着法 ${E.moveText(trace.bestMove)} · 访问 ${trace.visited} 节点 · 剪去 ${trace.prunedMoves} 个未展开子分支`:'调整深度或价值后会重新搜索，不复用旧树。')}</div><div id="trace-output">${trace?`${candidateHTML()}${principalHTML()}<div class="callout tiny">第 <span id="trace-counter">${cursor+1}</span> / ${trace.events.length} 个事件 · <span id="trace-event"></span></div><div class="action-row"><button data-action="play-trace">${playing&&traceMode==='events'?'暂停':'播放'}</button><button data-action="step-trace">单步</button><button data-action="reset-trace">回到根</button><button data-action="show-root">返回操作棋盘</button></div><input class="range" id="trace-range" aria-label="搜索轨迹进度" type="range" min="0" max="${trace.events.length-1}" value="${cursor}"><div class="row tiny"><span>节点来自真实递归；灰色分支尚未返回；≤/≥ 是剪枝返回界</span><button class="quiet tiny" data-action="tree-page">下一组节点</button></div><div class="tree" id="tree-host"></div>`:''}</div><p class="tiny muted" style="margin-top:14px">同分保留本次顺序的首个：坐标字典序按[x,y,nx,ny]从小到大；吃子优先按被吃子价值从大到小，再按坐标。Python目标练习按各题契约，最佳步练习固定坐标字典序；换排序时最优集合内的选中步可不同，最优分数应相同。剪枝数是未展开的直接子分支数量，不是推测的子树总节点。</p>`}
function principalHTML(){return `<div class="callout tiny" id="principal-line"><strong>主要变化线（principal variation）</strong><p>来自本次界面引擎的真实择优节点，与递归访问轨迹分开。Python提交仍由你的函数独立判题。同分保留本次走法顺序首个；有限深度高分不等于必胜。</p><ol>${trace.line.map((move,i)=>`<li>${(i%2===0?trace.side:E.opponent(trace.side))==='red'?'红方':'黑方'} ${E.moveText(move)}</li>`).join('')}</ol>${trace.line.length?'':`<p>${trace.nodes[0].reason==='terminal'?'根已终局':'深度为0'}，没有后续着法。</p>`}<span id="pv-counter">0</span><div class="action-row"><button data-action="play-pv" ${trace.line.length?'':'disabled'}>${playing&&traceMode==='pv'?'暂停':'播放变化线'}</button><button data-action="step-pv" ${trace.line.length?'':'disabled'}>变化线单步</button></div></div>`}
function candidateHTML(){const root=trace.nodes[0];return root.children.length?`<details class="candidates" open><summary>本次根节点候选 · ${trace.side==='red'?'红方取最大':'黑方取最小'}</summary><p class="tiny muted">≤/≥表示剪枝返回界，不能当作精确值；切到Minimax可逐项核对。点一行查看实际子节点。</p><div>${root.children.map(id=>{const n=trace.nodes[id],best=JSON.stringify(n.move)===JSON.stringify(trace.bestMove);return `<button class="candidate-row ${best?'active':''}" data-node="${id}" data-candidate="${id}" aria-label="${E.moveText(n.move)} 分数 ${n.bound==='upper'?'上界':n.bound==='lower'?'下界':'精确'} ${n.score}${best?' 最佳着法':''}"><span>${E.moveText(n.move)}</span><strong>${n.bound==='upper'?'≤ ':n.bound==='lower'?'≥ ':''}${n.score}${best?' · 最佳':''}</strong></button>`}).join('')}</div></details>`:''}
function focusSelector(element){if(!element)return null;if(element.id)return '#'+CSS.escape(element.id);for(const key of ['action','tab','lesson','unit','square','node'])if(element.dataset?.[key]!==undefined)return '[data-'+key+'='+JSON.stringify(element.dataset[key])+']';if(element.name)return '[name='+JSON.stringify(element.name)+'][value='+JSON.stringify(element.value)+']';return null;}
function visibleFocus(selector){if(!selector)return false;const element=$$(selector).find(el=>el.checkVisibility()&&!el.disabled);if(element){element.focus();return true}return false;}
function render({focus}={}){const calculation=$('#board-calculation');if(calculation)calculationVisibility.set(calculation.dataset.exercise,calculation.open);const active=document.activeElement,inside=$('#app').contains(active),selector=focus||(inside?focusSelector(active):null);const selection=active?.tagName==='TEXTAREA'?{start:active.selectionStart,end:active.selectionEnd,scroll:active.scrollTop}:null;const app=document.getElementById('app');app.innerHTML=layout();app.inert=!!$('.modal-backdrop');bind();if(view==='lab'){renderBoard();if(tab==='search'&&trace)renderTrace()}if(!app.inert&&visibleFocus(selector)&&selection&&document.activeElement.tagName==='TEXTAREA'){document.activeElement.setSelectionRange(selection.start,selection.end);document.activeElement.scrollTop=selection.scroll;}}
function renderBoard(keepEditor=false){
 if(!$('#board-host'))return;
 const focused=document.activeElement?.dataset.square;
 const display=editDraft?editDraft.board:traceBoard&&trace?trace.nodes[displayTraceNode()].board:b;
 const displaySide=editDraft?editDraft.side:traceBoard&&trace?trace.nodes[displayTraceNode()].side:side;
 const validity=validatePosition(display,displaySide),legal=!editDraft&&validity.canPlay?E.legalMoves(display,displaySide):[];
 const dest=selected&&!traceBoard&&!editDraft?legal.filter(m=>m[0]===selected[0]&&m[1]===selected[1]).map(m=>m.slice(2)):[];
 let lines='';for(let y=0;y<10;y++)lines+=`<line x1="0" y1="${y*100/9}" x2="100" y2="${y*100/9}"/>`;for(let x=0;x<9;x++)lines+=`<line x1="${x*12.5}" y1="0" x2="${x*12.5}" y2="44.44"/><line x1="${x*12.5}" y1="55.56" x2="${x*12.5}" y2="100"/>`;lines+='<path d="M37.5 0 L62.5 22.22 M62.5 0 L37.5 22.22 M37.5 77.78 L62.5 100 M62.5 77.78 L37.5 100"/>';
 $('#board-host').innerHTML=`<div class="board-wrap"><svg class="board-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><g stroke="#907746" stroke-width=".35" fill="none">${lines}</g><text x="18" y="51.5" fill="#957d50" font-size="4.8">楚 河</text><text x="65" y="51.5" fill="#957d50" font-size="4.8">汉 界</text></svg><div class="board-grid" role="group" aria-label="棋盘：左上坐标0,0">${display.flatMap((row,y)=>row.map((p,x)=>{const target=dest.some(m=>m[0]===x&&m[1]===y),active=!editDraft&&selected?.[0]===x&&selected?.[1]===y;return `<button class="square ${active?'selected':''} ${target?'target':''}" data-square="${x},${y}" tabindex="${boardFocus[0]===x&&boardFocus[1]===y?0:-1}" aria-pressed="${active}" aria-label="(${x},${y}) ${p==='.'?'空格':(E.owner(p)==='red'?'红':'黑')+esc(positions.pieceCodes[p]||p)}${target?' 合法目标':''}" ${traceBoard&&!editDraft?'disabled':''}>${p!=='.'?`<span class="piece ${E.owner(p)}">${esc(positions.pieceCodes[p]||p)}</span>`:''}<span class="coordinate">${x},${y}</span></button>`})).join('')}</div></div>`;
 $('#turn-label').textContent=`${displaySide==='red'?'红方':'黑方'}${editDraft?' · 摆棋草稿':'行棋'}${traceBoard&&!editDraft?' · 回放':''}`;
 $('#legal-count').textContent=!editDraft&&validity.canPlay?legal.length:'—';
 $('#evaluation').textContent=validity.canInspect?E.evaluate(display,saved.settings.values):'—';
 const terminal=!editDraft&&validity.canSearch?E.terminalScore(display,displaySide):null;
 $('#check-status').textContent=editDraft?'编辑中':!validity.canPlay?'局面待修正':terminal!==null?(E.inCheck(display,displaySide)?'将死判负':'困毙判负'):E.inCheck(display,displaySide)?'被将军':'可行棋';
 $('#board-note').textContent=editDraft?'点击格子放入所选棋子；暂存草稿不会改变正式棋盘，应用前必须通过校验。':!validity.canPlay?validity.errors.join(' '):traceBoard?`回放节点 #${displayTraceNode()}，操作暂锁定。点「返回操作棋盘」继续实验。`:boardMessage;
 if(!keepEditor||!editDraft)renderBoardDetail(display,displaySide,validity,terminal);
 else $('#score-detail').innerHTML=scoreHTML(display,displaySide,validity,terminal);
 const resetValues=$('#reset-values');if(resetValues)resetValues.onclick=()=>action('reset-values');
 $('#undo-board').disabled=!!editDraft||!session.history.length;
 $('#simulate-board').disabled=!!editDraft||!validatePosition(b,side).canPlay;
 const picker=$('#fixture-select');if(picker)picker.disabled=!!editDraft;
 for(const action of ['edit-board','switch-side','reset-board'])$(`[data-action=${action}]`).disabled=!!editDraft;
 for(const action of ['compute-search','compare-search']){const button=$(`[data-action=${action}]`);if(button)button.disabled=!!editDraft||!validatePosition(b,side).canSearch;}
 $$('[data-square]').forEach(el=>{el.onclick=()=>{boardFocus=el.dataset.square.split(',').map(Number);clickSquare(boardFocus)};el.onkeydown=event=>{if(event.key==='Escape'){selected=null;boardMessage='已取消选中。';renderBoard();return}const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[event.key];if(!delta)return;event.preventDefault();const [x,y]=el.dataset.square.split(',').map(Number),next=[x+delta[0],y+delta[1]];if(E.inside(...next)){boardFocus=next;$$('[data-square]').forEach(button=>button.tabIndex=button.dataset.square===next.join(',')?0:-1);$(`[data-square="${next}"]`).focus()}};});
 if(focused&&!traceBoard)$(`[data-square="${focused}"]`)?.focus();
}
function scoreHTML(display,displaySide,validity,terminal){if(!validity.canInspect)return'<p class="callout warning">棋盘格式或字符无效，暂不计算评分。</p>';const parts=E.evaluationParts(display,saved.settings.values);return `<details class="score-parts" open><summary>评分拆解 · 始终以红方为正</summary><div class="score-grid"><span>子力</span><strong id="score-material">${parts.material}</strong><span>兵卒推进</span><strong id="score-advance">${parts.advance}</strong><span>过河奖励</span><strong id="score-river">${parts.river}</strong><span>位置小计</span><strong id="score-position">${parts.position}</strong><span>原始合计</span><strong id="score-raw">${parts.rawTotal}</strong><span>限幅后静态评估</span><strong id="score-static">${parts.staticScore}</strong><span>终局分（${displaySide==='red'?'红':'黑'}方行动）</span><strong id="score-terminal">${terminal??'非终局 / 草稿'}</strong></div><p class="tiny muted">${parts.material} + ${parts.position} = ${parts.rawTotal}。${parts.clampDelta?`限幅调整 ${parts.clampDelta}，静态分限制为±99999。`:'未发生限幅。'}终局±100000另行覆盖静态分。</p><button id="reset-values" data-action="reset-values">恢复默认棋子价值</button></details>`}
function renderBoardDetail(display,displaySide,validity,terminal){
 const last=session.history.at(-1);
 $('#board-detail').innerHTML=`${editDraft?`<div class="board-editor callout"><h3>暂存摆棋</h3><p class="tiny">摆棋允许自由放置。应用后建立新的实验起点并清空旧历史；取消可保留正式棋盘。</p><div class="action-row"><label>放置棋子<select id="edit-piece">${['.','K','A','E','H','R','C','P','k','a','e','h','r','c','p'].map(p=>`<option value="${p}" ${editDraft.piece===p?'selected':''}>${p==='.'?'擦除':p+' '+positions.pieceCodes[p]}</option>`).join('')}</select></label><label>行动方<select id="edit-side"><option value="red" ${editDraft.side==='red'?'selected':''}>红方</option><option value="black" ${editDraft.side==='black'?'selected':''}>黑方</option></select></label></div><label class="tiny" for="board-text">10行×9格：.空格；K帅、A仕、E相、H马、R车、C炮、P兵；小写为黑方</label><textarea id="board-text" spellcheck="false" maxlength="2000">${esc(editDraft.text)}</textarea><p id="edit-status" role="status"></p><div class="action-row"><button class="primary" id="apply-board">应用局面</button><button id="cancel-board">取消编辑</button></div></div>`:`<p class="tiny" id="history-status">历史 ${session.history.length} 步${last?.kind==='move'?` · 最近 ${E.moveText(last.move)} · captured='${esc(last.captured)}'`:last?' · 最近手动换方':''}</p>${simulation?`<div class="callout" id="simulation-result" role="status">模拟 ${E.moveText(simulation.move)}，captured='${esc(simulation.captured)}'：${simulation.beforeScore} → ${simulation.afterScore}。${simulation.terminal!==null?'走后终局分 '+simulation.terminal+'。':''}棋盘、行动方和历史已完整还原。</div>`:''}<details class="coordinate-probe"><summary>坐标与棋子符号检查</summary><div class="action-row"><label>x<input id="probe-x" type="number" value="${boardFocus[0]}" step="1"></label><label>y<input id="probe-y" type="number" value="${boardFocus[1]}" step="1"></label><button id="probe-square">检查坐标</button></div><p id="probe-result" role="status"></p></details>`}<div id="score-detail">${scoreHTML(display,displaySide,validity,terminal)}</div>`;
 $('#computed-detail').replaceChildren($('#board-detail #score-detail'));
 if(editDraft){$('#edit-piece').onchange=event=>{editDraft.piece=event.target.value};$('#edit-side').onchange=readDraft;$('#board-text').oninput=readDraft;$('#apply-board').onclick=applyDraft;$('#cancel-board').onclick=()=>{editDraft=null;boardMessage='已取消摆棋，正式棋盘与历史保持原样。';renderBoard();visibleFocus('[data-action=edit-board]')};updateDraftStatus();}
 else $('#probe-square').onclick=()=>{const x=$('#probe-x').value,y=$('#probe-y').value,nx=Number(x),ny=Number(y);$('#probe-result').textContent=x.trim()&&y.trim()&&Number.isInteger(nx)&&Number.isInteger(ny)&&E.inside(nx,ny)?`board[${ny}][${nx}] = '${display[ny][nx]}'，阵营 ${E.owner(display[ny][nx])||'无'}。`:'越界或非整数字坐标；x须0–8，y须0–9。';};
}
function beginEdit(){clearBoardResult();selected=null;editDraft={board:E.clone(b),side,piece:'.',text:b.map(row=>row.join('')).join('\n')};renderBoard();$('#edit-piece').focus();}
function draftValidation(){return validatePosition(editDraft.text.split(/\r?\n/),editDraft.side)}
function updateDraftStatus(){const result=draftValidation();$('#edit-status').textContent=result.errors.length?result.errors.join(' ')+(result.canDisplay?'':' 预览保留上一个10×9网格。'):'局面可应用。'+result.warnings.join(' ');$('#apply-board').disabled=!result.canSearch;}
function readDraft(){editDraft.text=$('#board-text').value;editDraft.side=$('#edit-side').value;const result=draftValidation();if(result.canDisplay)editDraft.board=result.board;updateDraftStatus();renderBoard(true);}
function applyDraft(){const result=draftValidation();if(!result.canSearch){updateDraftStatus();return}clearBoardResult();adoptSession(L.createSession(result.board,editDraft.side,'custom'));editDraft=null;selected=null;persistLab();boardMessage='新实验局面已应用，旧历史与搜索结果已清空。';render({focus:'[data-action=edit-board]'});}
function undoBoard(){try{clearBoardResult();const undone=L.undo(session);adoptSession(undone.session);selected=undone.selection;persistLab();boardMessage=undone.record.kind==='move'?`已撤销 ${E.moveText(undone.record.move)}，还原 captured='${undone.record.captured}' 与${side==='red'?'红':'黑'}方行棋。`:'已撤销手动换方。';if(selected)boardFocus=selected.slice();render({focus:selected?'[data-square='+JSON.stringify(selected.join(','))+']':'[data-square='+JSON.stringify(boardFocus.join(','))+']'});}catch(error){boardMessage=error.message;renderBoard()}}
function clickSquare([x,y]){
 if(editDraft){editDraft.board[y][x]=editDraft.piece;editDraft.text=editDraft.board.map(row=>row.join('')).join('\n');renderBoard();return;}
 if(traceBoard)return;
 const p=b[y][x],validity=validatePosition(b,side),inspection=`board[${y}][${x}] = '${p}'，阵营 ${E.owner(p)||'无'}。`;
 if(E.owner(p)===side){selected=[x,y];const n=validity.canPlay?E.legalMoves(b,side).filter(m=>m[0]===x&&m[1]===y).length:0;boardMessage=inspection+(simulateMode?'模拟模式：':'')+`有 ${n} 个合法目标。`;renderBoard();return;}
 if(selected&&validity.canPlay){const move=[...selected,x,y];try{
   if(simulateMode){const result=L.simulate(session,move,saved.settings.values);clearBoardResult();simulation=result;selected=null;boardMessage='模拟已还原；可继续操作原局面。';renderBoard();return;}
   const next=L.playMove(session,move,selected);clearBoardResult();adoptSession(next);selected=null;persistLab();const captured=session.history.at(-1).captured;boardMessage=`${session.history.at(-1).sideBefore==='red'?'红':'黑'}方 ${E.moveText(move)}，captured='${captured}'；起点为空，终点为${b[y][x]}。`;
   if(tab==='search'){$('#panel-body').innerHTML=searchHTML();bindPanel()}renderBoard();return;
 }catch(error){boardMessage=inspection+'这步不合法：'+error.message;renderBoard();return;}}
 boardMessage=inspection;renderBoard();
}
function bind(){ const calculation=$('#board-calculation');if(calculation){const lessonId=current.id;calculation.ontoggle=()=>calculationVisibility.set(lessonId,calculation.open);} $$('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));$$('[data-lesson]').forEach(el=>el.onclick=()=>setLesson(el.dataset.lesson));$$('[data-unit]').forEach(el=>el.onclick=()=>setLesson(exercises.find(e=>e.unit_id===Number(el.dataset.unit)).id));$$('[data-resolve]').forEach(el=>el.onclick=()=>{delete saved.mistakes[el.dataset.resolve];save();render()});if($('#mobile-lesson'))$('#mobile-lesson').onchange=e=>setLesson(e.target.value);if($('#fixture-select'))$('#fixture-select').onchange=e=>{clearBoardResult();editDraft=null;const p=allFixtures().find(p=>p.id===e.target.value);try{const next=L.createSession(p?p.board:current.lab.board,p?p.sideToMove:current.lab.side,p?p.id:'lesson');adoptSession(next);selected=null;persistLab();boardMessage=p?(p.purposeZh||p.title):current.lab.objective;render()}catch(error){e.target.value=selectedFixture;boardMessage='该教学局面不能进入行棋实验：'+error.message+'；当前棋盘与记录保留。可在摆棋草稿中检查规则反例。';renderBoard()}};bindPanel()}
function bindPanel(){ $$('[data-tab]').forEach(el=>el.onclick=()=>{if(tab==='search'&&el.dataset.tab!=='search'){cancelSearch();stopPlay();traceBoard=false;}tab=el.dataset.tab;render()});$$('#panel-body [data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));for(const [selector,scope,runButton] of [['#code-editor','core','#run-visible'],['#transfer-editor','transfer','#run-transfer']]){const editor=$(selector);if(!editor)continue;editor.oninput=()=>{if(scope==='core'){saved.codes[current.id]=editor.value;save();if(coreChecks.has(current.id))setPythonStatus(pythonBusy?'运行期间代码已修改，本次结果只对应提交时快照。':'代码已修改，上次结果只对应旧提交；请重新运行示例或挑战。','','core');refreshProgress()}else{updateTransfer({code:editor.value});$('#transfer-record-status').textContent=transferRecordStatus()}};editor.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();$(pythonBusy?(scope==='core'?'#stop-python':'#stop-transfer'):runButton).focus()}if(e.key==='Tab'&&!e.shiftKey){e.preventDefault();const i=editor.selectionStart,j=editor.selectionEnd;if(editor.value.length-(j-i)+4>MAX_CODE_CHARS){setPythonStatus('代码已达100000字符上限；删减或选中内容后再缩进。','fail',scope);return}editor.setRangeText('    ',i,j,'end');editor.dispatchEvent(new Event('input'))}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();if(!pythonBusy)runPython(scope==='transfer',scope)}}}if($('#reflection-editor'))$('#reflection-editor').oninput=e=>{saved.reflections[current.id]=e.target.value;save()};if($('#transfer-explanation'))$('#transfer-explanation').oninput=e=>updateTransfer({explanation:e.target.value});for(const id of ['search-depth','search-algo','search-order'])if($('#'+id))$('#'+id).onchange=()=>{readSearchSettings();computeSearch()};$$('[data-weight]').forEach(el=>{el.oninput=()=>{cancelSearch();stopPlay();trace=null;traceBoard=false;readSearchSettings();$('#trace-output')?.replaceChildren();showSearchStatus('参数已修改，旧结果已失效；完成编辑后重新计算。');renderBoard()};el.onchange=()=>{readSearchSettings();computeSearch()}});if($('#trace-range'))$('#trace-range').oninput=e=>{stopPlay();traceMode='events';cursor=Number(e.target.value);traceBoard=true;renderTrace();renderBoard()}}
function action(a){if(a==='map'){clearBoardResult();view='map';render()}else if(a==='review'){clearBoardResult();view='review';render()}else if(a==='next'){setLesson(exercises[(exercises.indexOf(current)+1)%exercises.length].id)}else if(a==='reset-board'){clearBoardResult();editDraft=null;adoptSession(L.reset(session));selected=null;persistLab();boardMessage='已恢复本次实验初始棋盘、行动方与空历史。';render()}else if(a==='reset-values'){clearBoardResult();saved.settings.values={...E.VALUES};save();boardMessage='已恢复默认棋子价值；需要搜索时请重新计算。';render();}else if(a==='switch-side'){try{clearBoardResult();editDraft=null;adoptSession(L.switchSide(session,selected));selected=null;persistLab();render()}catch(error){boardMessage=error.message;renderBoard()}}else if(a==='edit-board')beginEdit();else if(a==='undo-board')undoBoard();else if(a==='simulate-board'){clearBoardResult();simulateMode=true;boardMessage='模拟模式：选己方棋子再选合法目标；计算后立即还原，历史不增加。';renderBoard()}else if(a==='reload-storage')reloadLatest();else if(a==='hint'){saved.hints[current.id]=Math.min(3,(saved.hints[current.id]||0)+1);save();render()}else if(a==='solution'){modal(`<h2>参考解答</h2><p class="muted">这是一个实现。先解释为什么它通过测试，再对照自己的代码。不会替换编辑器。</p><pre class="solution">${esc(current.solution)}</pre><p>${esc(current.transfer)}</p>`)}else if(a==='transfer-position'){clearBoardResult();editDraft=null;const t=currentTransfer();adoptSession(L.createSession(t.lab.board,t.lab.side,t.lab.id));selected=null;persistLab();boardMessage=t.title+'；按本单元知识检验右侧新输入。';render()}else if(a==='run-transfer')runPython(true,'transfer');else if(a==='transfer-hint'){updateTransfer({hints:Math.min(3,transferAnswer().hints+1)});render()}else if(a==='transfer-solution'){updateTransfer({answerViewed:true});modal(`<h2>迁移参考解答</h2><p>这是一个实现，查看不等于通过；不会填入你的编辑器。</p><pre class="solution">${esc(currentTransfer().solution)}</pre><p>${esc(currentTransfer().basis)}</p>`)}else if(a==='save-reflection'){saveReflection()}else if(a==='save-transfer-explanation'){saveTransferExplanation()}else if(a==='restore-starter'){if(confirm('将当前题代码恢复为空白脚手架？其他题记录不变。')){saved.codes[current.id]=current.starter;coreChecks.delete(current.id);resultText='目标函数已恢复为空白，请重新填写与运行。';resultType='';save();render()}}else if(a==='run-visible')runPython(false);else if(a==='run-hidden')runPython(true);else if(a==='stop-python')stopPython('运行已停止；Worker 已终止，代码保留。');else if(a==='check-prediction'){const checked=$('input[name=prediction]:checked');if(!checked)return;saved.predictions[current.id]={choice:Number(checked.value)};calculationVisibility.set(current.id,true);if($('#board-calculation'))$('#board-calculation').open=true;save();render()}else if(a==='compute-search')computeSearch();else if(a==='compare-search')compareSearch();else if(a==='stop-search'){cancelSearch();stopPlay();trace=null;traceBoard=false;showSearchStatus('搜索计算已终止，旧结果已失效。');render()}else if(a==='play-trace')playTrace('events');else if(a==='play-pv')playTrace('pv');else if(a==='step-trace'){stopPlay();traceMode='events';cursor=Math.min(trace.events.length-1,cursor+1);traceBoard=true;renderTrace();renderBoard()}else if(a==='step-pv'){stopPlay();traceMode='pv';pvCursor=Math.min(trace.principalNodes.length-1,pvCursor+1);traceBoard=true;renderTrace();renderBoard()}else if(a==='reset-trace'){stopPlay();cursor=0;pvCursor=0;traceBoard=true;renderTrace();renderBoard()}else if(a==='show-root'){stopPlay();traceBoard=false;selected=null;renderBoard()}else if(a==='tree-page'){tracePage=(tracePage+1)%Math.ceil(trace.nodes.length/50);renderTrace()}else if(a==='storage')storageModal();else if(a==='about')aboutModal();else if(a==='diagnosis')diagnosisModal()}
async function saveReflection(){const eid=current.id,text=$('#reflection-editor').value;if(!text.trim()){reflectionMessage='先写出你自己的解释或一个反例。';$('#reflection-status').textContent=reflectionMessage;return}saved.reflections[eid]=text;const persisted=await save();if(current.id!==eid)return;reflectionMessage=persisted?'解释已保存。对照下方问题自行检查；未自动判定解释正确。':'解释仅在本页，请导出备份。';if($('#reflection-status'))$('#reflection-status').textContent=reflectionMessage;}
async function saveTransferExplanation(){const id=currentTransfer().id,text=$('#transfer-explanation').value;if(!text.trim()){$('#transfer-explanation-status').textContent='请先写一个具体输入、结论与局限。';return}const persisted=await updateTransfer({explanation:text});if(currentTransfer().id===id&&$('#transfer-explanation-status'))$('#transfer-explanation-status').textContent=persisted?'解释已保存。逐项自行核对；尚未由真人验证。':'解释仅在本页，请导出备份。';}
function modal(html){const previous=document.activeElement,opener=focusSelector(previous),el=document.createElement('div');el.className='modal-backdrop';el.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="实验室信息"><button class="close" aria-label="关闭">✕</button>${html}</section>`;document.body.append(el);$('#app').inert=true;let closed=false;const close=()=>{if(closed)return;closed=true;el.remove();$('#app').inert=!!$('.modal-backdrop');if(!$('#app').inert){if(previous?.isConnected&&previous.checkVisibility())previous.focus();else if(!visibleFocus(opener))visibleFocus('#lesson-title')}};el.querySelector('.close').onclick=close;el.onclick=e=>{if(e.target===el)close()};el.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}if(e.key==='Tab'){const f=[...el.querySelectorAll('button,input,select,a,textarea,[tabindex]')].filter(x=>!x.disabled&&x.tabIndex>=0&&x.checkVisibility());const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};el.querySelectorAll('pre.solution').forEach(pre=>pre.tabIndex=0);el.querySelector('.close').focus();return el;}
function downloadRecord(raw,name,type='application/json'){const url=URL.createObjectURL(new Blob([raw],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function storageModal(){
 const el=modal(`<h2>当前浏览器的学习记录</h2><p id="storage-summary">保存 ${Object.keys(saved.codes).length} 份代码，已通过 ${saved.passed.length} / ${exercises.length} 题。没有服务器进度同步；另一台设备需手动导入。</p><div class="action-row"><button class="primary" id="export-data">导出 JSON 备份</button><label><span class="tiny">导入备份（最大16 MB）</span><input id="import-data" type="file" accept="application/json,.json"></label></div>${protectStoredRecord?`<div class="callout warning storage-recovery"><p>原记录仍保留。当前修改仅在本次页面中；导入有效备份或明确保存当前记录后，才会替换原记录。</p><div class="action-row">${invalidStoredRaw!==null?'<button id="export-original">导出损坏原记录</button>':''}<button id="save-recovered">保存当前记录，替换原记录</button></div></div>`:''}${storageConflict?'<div class="callout warning"><p>另一页更新了学习记录。本页草稿仍保留，请先导出，再载入最新记录。</p><button id="modal-reload-latest">载入最新记录</button></div>':''}<p id="import-status" role="status"></p><p class="tiny muted">导入会合并代码、进度、提示、预测和复习记录。同题代码和明确提供的实验设置以导入内容为准；省略的设置保留当前值。仅恢复文本，不执行代码。</p>`);
 let importGeneration=0;const reload=el.querySelector('#modal-reload-latest');if(reload)reload.onclick=reloadLatest;
 const status=message=>{el.querySelector('#import-status').textContent=message};
 const refreshed=()=>{el.querySelector('.storage-recovery')?.remove();el.querySelector('#storage-summary').textContent=`保存 ${Object.keys(saved.codes).length} 份代码，已通过 ${saved.passed.length} / ${exercises.length} 题。没有服务器进度同步；另一台设备需手动导入。`};
 el.querySelector('#export-data').onclick=()=>{try{downloadRecord(encodeRecord(saved,exercises,E.VALUES,{backup:true,...stateOptions()}),'象棋实验室-学习记录.json');status('备份已导出，包含代码、学习记录和实验设置。')}catch(error){status('导出失败：'+error.message)}};
 if(el.querySelector('#export-original'))el.querySelector('#export-original').onclick=()=>downloadRecord(invalidStoredRaw,'象棋实验室-损坏原记录.txt','text/plain');
 if(el.querySelector('#save-recovered'))el.querySelector('#save-recovered').onclick=async()=>{if(!confirm('这会替换原浏览器记录。建议先导出损坏原记录，再保存当前学习记录。继续？'))return;importGeneration++;try{await writeStored(()=>encodeRecord(saved,exercises,E.VALUES,stateOptions()));protectStoredRecord=false;invalidStoredRaw=null;showStorageWarning('');render();refreshed();status('当前学习记录已保存，可安全刷新。')}catch(error){status('保存失败：'+error.message+'；原记录仍保留。')}};
 el.querySelector('#import-data').onchange=async event=>{
  const request=++importGeneration;
  try{
   const file=event.target.files[0];if(!file)return;if(file.size>MAX_RECORD_BYTES)throw Error('文件超过16 MB');
   const text=await file.text();if(request!==importGeneration||!el.isConnected)return;
   const incoming=parseRecord(text,exercises,E.VALUES,{backup:true,...stateOptions()});
   let candidate;
   // A failed validation or persistence leaves both memory and local bytes untouched.
   if(pythonBusy)stopPython('正在导入有效备份，已停止本页Python运行；代码保留。');
   await writeStored(()=>{candidate=mergeRecord(saved,incoming,exercises,E.VALUES,stateOptions());return encodeRecord(candidate,exercises,E.VALUES,stateOptions())},()=>request===importGeneration&&el.isConnected,()=>{saved=candidate});
   if(request!==importGeneration||!el.isConnected)return;
   protectStoredRecord=false;invalidStoredRaw=null;showStorageWarning(storageConflict?conflictMessage:'');
   setLesson(saved.lastExercise||current.id,true,false);refreshed();
   status('导入成功：代码、学习记录和实验设置已保存。关闭窗口即可继续。');
  }catch(error){if(request===importGeneration&&el.isConnected)status('导入失败：'+error.message+'；当前记录未更改。')}
 };
}
function aboutModal(){modal(`<h2>规则与边界</h2><p>七类棋子、蹩马腿、塞象眼、炮架、将帅照面、自将过滤、将死与困毙都参与真实运算。将帅攻击只用于判将军，不提供「吃将」作为正常合法着法。</p><p>本版是短局面教学引擎，不裁定长将、长捉、重复局面与自然限着；不是完整竞赛裁判程序。无合法着法的一方负，包括未被将军的困毙。</p><p>分数固定红方视角。兵的推进与过河奖励是教学设计，不是专业引擎参数。30 个局面是原创教学构造，不声称均可从标准开局实际达到。</p><h3>Python 执行范围</h3><p>代码在当前设备的独立 Web Worker 中用本地打包 Pyodide 执行。没有远程付费 API。停止或 3 秒计算超时会终止 Worker；首次加载另设 45 秒上限。</p><p>这是教育用途隔离，不是运行恶意代码的安全边界。不要粘贴不可信代码。挑战测试在运行前不展示，保存在前端，并非防作弊安全评测。</p><h3>规则依据</h3>${positions.sources.map(s=>`<p class="tiny"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title||s.titleZh||s.name||s.url)}</a></p>`).join('')}<p class="tiny muted">课程与测试由开发代理验证；未进行真实学生访谈，也未验证学习收益或留存率。版本 0.1.0。</p>`)}
const diagnostic=[{q:'board[y][x] 中，(2,7) 对应哪个索引？',c:['board[2][7]','board[7][2]','board[7+2]'],a:1,u:1},{q:'一着符合走子规则，但暴露自己的帅。它是合法着法吗？',c:['合法','不合法','只有红方不合法'],a:1,u:3},{q:'撤销一次吃子，至少需要保留什么？',c:['只有终点','起终点与被吃棋子','只有评分'],a:1,u:4},{q:'红方视角评分中，黑方节点应选择什么？',c:['最大分','最小分','始终第一着'],a:1,u:6}];
function diagnosisModal(){const el=modal(`<h2>4 个问题，找到起点</h2><p class="muted">无需写代码。答完后得到建议，也可直接跳过自由预览。</p>${diagnostic.map((d,i)=>`<div class="diagnosis-item"><strong>${i+1}. ${d.q}</strong>${d.c.map((c,j)=>`<label class="prediction-choice"><input type="radio" name="d${i}" value="${j}">${c}</label>`).join('')}</div>`).join('')}<button class="primary" id="diagnose-submit">查看建议</button><p id="diagnose-result" role="status"></p>`);el.querySelector('#diagnose-submit').onclick=()=>{const answers=diagnostic.map((d,i)=>el.querySelector(`input[name=d${i}]:checked`));if(answers.some(a=>!a)){el.querySelector('#diagnose-result').textContent='请先回答全部 4 题，或关闭诊断自由预览。';return}const wrong=diagnostic.filter((d,i)=>Number(answers[i].value)!==d.a),u=wrong[0]?.u||7;saved.diagnosed=true;saved.diagnostic={answers:answers.map(a=>Number(a.value)),suggestedUnit:u,at:new Date().toISOString()};save();el.querySelector('#diagnose-result').innerHTML=`答对 ${4-wrong.length}/4 题。建议从单元 ${u}「${esc(units.find(x=>x.id===u).title)}」开始。 <button id="diagnose-start">进入建议单元</button>`;el.querySelector('#diagnose-start').onclick=()=>{el.querySelector('.close').click();setLesson(exercises.find(e=>e.unit_id===u).id)}}}
function readSearchSettings(){saved.settings.depth=Number($('#search-depth').value);saved.settings.algo=$('#search-algo').value;saved.settings.order=$('#search-order').value;$$('[data-weight]').forEach(el=>{saved.settings.values[el.dataset.weight]=Math.max(0,Math.min(10000,Number(el.value)||0))});save()}
function cancelSearch(){stopPlay();searchGeneration++;for(const job of searchJobs){clearTimeout(job.timer);job.worker.terminate();job.reject(Error('搜索已停止'));}searchJobs.clear();searchMessage='';}
