function refreshSearchOutput(){const host=$('#trace-output');if(host){const template=document.createElement('template');template.innerHTML=searchHTML();host.replaceChildren(...template.content.querySelector('#trace-output').childNodes);$('#search-status').textContent=template.content.querySelector('#search-status').textContent;bindPanel();renderTrace()}renderBoard()}
function searchJob(snapshot,runSide,depth,options){return new Promise((resolve,reject)=>{const worker=new Worker('./search-worker.js',{type:'module'}),job={worker,reject,timer:null};searchJobs.add(job);const finish=()=>{clearTimeout(job.timer);worker.terminate();searchJobs.delete(job)};job.timer=setTimeout(()=>{finish();reject(Error('搜索超过 8 秒教学预算，请降低深度。'))},8000);worker.onmessage=({data})=>{finish();data.error?reject(Error(data.error)):resolve(data.result)};worker.onerror=e=>{finish();reject(Error('搜索 Worker 错误：'+e.message))};try{worker.postMessage({board:snapshot,side:runSide,depth,options})}catch(error){finish();reject(error)}})}
async function computeSearch(){if(tab!=='search')return;if(editDraft||!validatePosition(b,side).canSearch){showSearchStatus('当前局面不能搜索：请先完成摆棋，并校验行棋方与将帅状态。');return;}readSearchSettings();cancelSearch();const generation=searchGeneration,snapshot=E.clone(b),runSide=side,settings=structuredClone(saved.settings);stopPlay();trace=null;traceBoard=false;showSearchStatus('正在独立 Worker 中计算真实搜索树…');refreshSearchOutput();try{const result=await searchJob(snapshot,runSide,settings.depth,{prune:settings.algo==='alphabeta',values:settings.values,order:settings.order});if(generation!==searchGeneration)return;trace=result;cursor=0;pvCursor=0;traceMode='events';tracePage=0;traceBoard=true;searchMessage='';refreshSearchOutput()}catch(error){if(generation===searchGeneration){showSearchStatus(error.message);refreshSearchOutput()}}}
function renderTrace(){if(!trace||!$('#tree-host'))return;const focusedNode=$('#tree-host').contains(document.activeElement)?document.activeElement.dataset.node:null;const ev=trace.events[cursor],n=trace.nodes[traceMode==='pv'?trace.principalNodes[pvCursor]:ev.id],entered=new Set(),returned=new Set();for(let i=0;i<=cursor;i++){const e=trace.events[i];if(e.type==='enter')entered.add(e.id);if(e.type==='return')returned.add(e.id)}const pv=$('#pv-counter');if(pv)pv.textContent=`变化线 ${pvCursor} / ${trace.line.length} 步${traceMode==='pv'?' · 当前回放':''}`;$('#trace-counter').textContent=cursor+1;$('#trace-event').textContent=ev.type==='enter'?`进入 #${n.id}，${n.side==='red'?'MAX 红方':'MIN 黑方'}，剩余 ${n.depth} 层`:ev.type==='return'?`#${n.id} 返回 ${n.bound==='upper'?'上界 ≤ ':n.bound==='lower'?'下界 ≥ ':'精确分数 '}${ev.score}（${n.reason==='terminal'?'终局':n.reason==='evaluation'?'静态评估':'子节点比较'}）`:`#${n.id} α=${ev.alpha} ≥ β=${ev.beta}，剪去 ${ev.moves.length} 个子分支`;if(traceMode==='pv'){for(const id of trace.principalNodes.slice(0,pvCursor+1)){entered.add(id);returned.add(id)}$('#trace-event').textContent=`变化线 #${n.id} · ${n.side==='red'?'红':'黑'}方行动 · d${n.depth} · 精确分数 ${n.score}`;}$('#trace-range').value=cursor;const ns=trace.nodes.slice(tracePage*50,tracePage*50+50);$('#tree-host').innerHTML=ns.map(node=>{let level=0,p=node.parent;while(p!==null){level++;p=trace.nodes[p].parent}return `<button class="tree-node ${node.id===n.id?'current':''}" style="padding-left:${7+level*12}px;opacity:${entered.has(node.id)?1:.4}" data-node="${node.id}"><span>${node.side==='red'?'▲':'▼'} #${node.id}</span><small>${E.moveText(node.move)} · d${node.depth}</small><span class="score">${returned.has(node.id)?(node.bound==='upper'?'≤ ':node.bound==='lower'?'≥ ':'')+node.score:'…'}</span></button>${node.skipped.length&&returned.has(node.id)?`<div class="tree-node pruned" style="padding-left:${19+level*12}px">✂ ${node.skipped.length} 个未展开分支：${node.skipped.slice(0,3).map(E.moveText).join(' / ')}${node.skipped.length>3?' …':''}</div>`:''}`}).join('');$$('[data-node]').forEach(el=>el.onclick=()=>{stopPlay();const id=Number(el.dataset.node);traceMode='events';cursor=trace.events.findIndex(e=>e.id===id&&e.type==='enter');traceBoard=true;renderTrace();renderBoard()});if(focusedNode!==null)visibleFocus('#tree-host [data-node='+JSON.stringify(focusedNode)+']')}
function stopPlay(){if(playing)clearInterval(playing);playing=null;for(const [action,label] of [['play-trace','播放'],['play-pv','播放变化线']]){const button=$(`[data-action=${action}]`);if(button)button.textContent=label;}}
function displayTraceNode(){return traceMode==='pv'?trace.principalNodes[pvCursor]:trace.events[cursor].id;}
function playTrace(mode){
 if(playing){stopPlay();return;}if(!trace)return;traceMode=mode;const source=trace,generation=searchGeneration;
 if(mode==='pv'){if(pvCursor>=source.principalNodes.length-1)pvCursor=0;}else if(cursor>=source.events.length-1)cursor=0;
 traceBoard=true;renderTrace();renderBoard();
 playing=setInterval(()=>{if(trace!==source||generation!==searchGeneration||tab!=='search'||view!=='lab'){stopPlay();return;}
  if(mode==='pv'){if(pvCursor<source.principalNodes.length-1)pvCursor++;else{stopPlay();return;}}
  else{if(cursor<source.events.length-1)cursor++;else{stopPlay();return;}}
  renderTrace();renderBoard();
 },650);
 const button=$(`[data-action=${mode==='pv'?'play-pv':'play-trace'}]`);if(button)button.textContent='暂停';
}

async function compareSearch(){if(editDraft||!validatePosition(b,side).canSearch){showSearchStatus('当前局面不能比较：请先完成摆棋并通过局面校验。');return;}readSearchSettings();cancelSearch();const generation=searchGeneration,snapshot=E.clone(b),runSide=side,settings=structuredClone(saved.settings);stopPlay();trace=null;traceBoard=false;showSearchStatus('正在比较同一局面两种算法的真实最优分数…');refreshSearchOutput();try{const results=[];for(const prune of [false,true]){const result=await searchJob(snapshot,runSide,settings.depth,{prune,values:settings.values,order:settings.order});if(generation!==searchGeneration)return;results.push(result)}showSearchStatus(`Minimax ${results[0].score} / ${results[0].visited} 节点；Alpha-beta ${results[1].score} / ${results[1].visited} 节点，剪去 ${results[1].prunedMoves} 子分支。${results[0].score===results[1].score?'最优分数一致。':'分数不一致，需检查引擎。'}`)}catch(error){if(generation===searchGeneration)showSearchStatus(error.message)}}
function setPythonStatus(text,type='',scope=pythonScope){if(scope==='core'){resultText=text;resultType=type}else{transferResultText=text;transferResultType=type}const result=$(scope==='core'?'#python-result':'#transfer-result');if(result){result.textContent=text;result.className='result '+type}for(const id of ['run-visible','run-hidden','run-transfer'])if($('#'+id))$('#'+id).disabled=pythonBusy;for(const id of ['stop-python','stop-transfer'])if($('#'+id))$('#'+id).disabled=!pythonBusy;}
async function runPython(hidden,scope='core'){
 if(pythonBusy)return;pythonScope=scope;
 try{const runToken=++pythonResultGeneration,exercise=scope==='core'?current:currentTransfer(),eid=exercise.id,code=$(scope==='core'?'#code-editor':'#transfer-editor').value;
  if(scope==='core'){saved.codes[eid]=code;save()}else updateTransfer({code});pythonBusy=true;setPythonStatus('正在加载本地 Python 运行环境…（首次约数秒）','',scope);
  const worker=pythonWorker=new Worker('./python-worker.js');clearTimeout(pythonTimer);pythonTimer=setTimeout(()=>stopPython('Python 环境加载超过 45 秒。可重试；页面和代码仍可操作。'),45000);
  worker.onmessage=async e=>{if(worker!==pythonWorker)return;const data=e.data;
   if(data.phase==='running'){clearTimeout(pythonTimer);pythonTimer=setTimeout(()=>stopPython('计算超过 3 秒，Worker 已终止。检查是否有无限循环或过深递归。','fail'),3000);setPythonStatus('正在执行你的 Python 函数与'+(scope==='transfer'?'迁移自查':hidden?'挑战':'示例')+'测试…','',scope);return}if(data.phase==='loading')return;
   clearTimeout(pythonTimer);worker.terminate();pythonWorker=null;pythonBusy=false;
   if(data.error){if(data.stage==='loading'){setPythonStatus('Python环境加载失败：'+data.error+'。可重试；代码保留。','fail',scope);return}if(scope==='core'){saved.mistakes[eid]={message:data.error.slice(-500),at:new Date().toISOString()};save();coreChecks.set(eid,{source:code,passed:0,total:1,challenge:hidden});refreshProgress()}const changed=scope==='core'?saved.codes[eid]!==code:transferAnswer().code!==code;setPythonStatus(errorSummary(data.error)+(changed?'\n当前草稿已修改；此错误仅对应提交时快照，请重新运行。':'')+'\n下一步：'+feedbackTip(data.error,scope)+'\n\n详细错误（回溯保留供定位）：\n'+data.error,'fail',scope);return}
   const r=data.result;if(!r||!Number.isInteger(r.total)||r.total<=0||!Number.isInteger(r.passed)||r.passed<0||r.passed>r.total){setPythonStatus('判题未返回有效测试，不能计为通过；请重新运行。','fail',scope);return}const ok=r.passed===r.total;
   if(scope==='core'){coreChecks.set(eid,{source:code,passed:r.passed,total:r.total,challenge:hidden});if(hidden&&ok&&!saved.passed.includes(eid))saved.passed.push(eid);if(!ok)saved.mistakes[eid]={message:r.tests.filter(t=>!t.ok).map(t=>t.name+': '+t.message).join('; ').slice(0,500),at:new Date().toISOString()};}
   else saved.transfers[eid]={...saved.transfers[eid],lastCheck:{source:code,passed:r.passed,total:r.total,at:new Date().toISOString()}};
   const persisted=await save();if(scope==='core')refreshProgress();if(runToken!==pythonResultGeneration||(scope==='core'?current.id!==eid:currentTransfer().id!==eid))return;
   const changed=scope==='core'?saved.codes[eid]!==code:transferAnswer().code!==code;
   setPythonStatus(`${scope==='transfer'?'迁移自查':hidden?'挑战':'示例'}测试 ${r.passed}/${r.total} 通过\n`+r.tests.map(t=>`${t.ok?'✓':'✗'} ${t.name}${t.ok?'':'\n  '+t.message}`).join('\n')+(r.stdout?'\n\n输出：\n'+r.stdout:'')+(r.stdoutTruncated?'\n（标准输出达到16000字符上限，已截断。）':'')+(r.feedbackTruncated?'\n（测试反馈达到展示上限，已截断。）':'')+(!ok?'\n\n下一步：'+feedbackTip(r.tests.filter(t=>!t.ok).map(t=>t.message).join(' '),scope):'')+(changed?'\n当前草稿已修改；本结果只对应提交时快照，需重新运行。':'')+(scope==='transfer'?'\n解释需自行核对；测试通过不增加核心24题计数。':hidden&&ok?(persisted?'\n\n挑战通过，学习进度已保存在当前浏览器。':'\n\n挑战通过；学习进度仅保留在本次页面，请导出备份。'):'')+(scope==='transfer'&&!persisted?'\n本次作答仅在本页，请导出备份。':''),ok?'success':'fail',scope);
   if(scope==='core')refreshProgress();if(scope==='transfer'&&$('#transfer-record-status'))$('#transfer-record-status').textContent=transferRecordStatus();
  };
  worker.onerror=e=>{if(worker===pythonWorker)stopPython('Worker 加载失败：'+String(e.message).slice(0,1000),'fail')};worker.postMessage({code,exercise,hidden});
 }catch(error){stopPython('Python Worker 加载失败：'+String(error.message||error).slice(0,1000),'fail')}
}
function stopPython(message,type=''){pythonResultGeneration++;if(pythonWorker)pythonWorker.terminate();pythonWorker=null;clearTimeout(pythonTimer);pythonBusy=false;setPythonStatus(message,type)}

try{({curriculum,positions,transfers,activities,exercises,units}=await loadContent());if(window.xiangqiBootExpired)throw Error('启动等待已超时，请重新加载。');restoreLocalState();const lessonId=()=>{try{return decodeURIComponent(location.hash.slice(1))}catch{return ''}};setLesson(lessonId()||saved.lastExercise,false,false);addEventListener('hashchange',()=>setLesson(lessonId(),false));if(!protectStoredRecord&&!saved.diagnosed&&!saved.lastSeen){saved.lastSeen=new Date().toISOString();save();diagnosisModal()}}catch(err){if(!window.xiangqiBootExpired){$('#app').innerHTML=`<main class="workspace" role="alert"><h1>实验室暂未加载</h1><p>${esc(err.message)}</p><button id="retry-load">重新加载</button><p class="muted">浏览器中的原学习记录仍保留。资料恢复后可继续自己的代码。</p></main>`;$('#retry-load').onclick=()=>location.reload()}}
